import json
from pathlib import Path
out=Path('work/pilot-v1')
cases=[]; keys=[]
def add(id,prompt,options,family,gold,change,derivation,rubric,over=(),reject=()):
    cases.append(dict(id=id,prompt=prompt,options=dict(zip('ABCD',options))))
    keys.append(dict(id=id,family=family,gold=gold,initial_claim_should_change=change,derivation=derivation,scope_rubric=rubric,scope_overclaim_options=list(over),false_rejection_options=list(reject)))
add('R01',
'A device is faulty with probability 1/4. Operating costs 16 if faulty and 0 otherwise; replacing costs 6 in either state. Minimize expected total cost. Initially, without a test, the conclusion was to operate. Before acting, a perfect test becomes available for 3, paid whatever its result. After testing, either action remains available. No other information or action exists. Assess the initial recommendation ex ante, before buying the test.',
['Test, then replace only if faulty; any perfect information improves expected total cost.', 'Replace immediately; its worst possible cost is lower.', 'Retain operating: its expected cost is 4, versus 4.5 for optimal testing.', 'Retain operating: its realized cost is at most 4.'],
'value_of_information','C',False,'Operate: 16/4=4. Test: 3+6/4=4.5. Replace: 6.','Compare ex ante expectations including the fee; do not claim a pathwise bound.',('A','D'))
