for c in cases:
    c['prompt'] += ' Give one choice and a brief warrant with its scope.'
for name,data in [('cases.json',cases),('key.json',keys)]:
    (out/name).write_text(json.dumps({'cases':data},indent=2,ensure_ascii=False)+'\n')
print('Wrote cases.json and key.json')
